_HEX = '0123456789abcdef'
_ALNUM = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
# Google's FCM registration tokens use this alphabet, not plain alnum.
_TOKEN = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_'


def get_random_string(kind, length=32):
	"""A random string of the alphabet `kind` asks for.

	'hex'          -> lowercase hex, for adids and the like
	'google_token' -> the FCM alphabet, for push tokens
	anything else  -> alnum
	"""
	alphabet = {'hex': _HEX, 'google_token': _TOKEN}.get(kind, _ALNUM)
	return ''.join(random.choice(alphabet) for _ in range(int(length)))


def perform_campaign_data_checks(campaign_data):
	"""Cheap sanity check on the campaign block, before anything is sent."""
	if not isinstance(campaign_data, dict):
		raise ValueError("campaign_data must be a dict")
	adjust = campaign_data.get('adjust') or {}
	token = adjust.get('app_token')
	if not token or len(token) != 12:
		raise ValueError("Malformed App Token %r" % (token,))
	if not campaign_data.get('package_name'):
		raise ValueError("campaign_data needs a package_name")
	return True

def md5(data, radix=16):
	import hashlib
	md5_obj = hashlib.md5()
	md5_obj.update(data)
	if radix == 16:
		return md5_obj.hexdigest()
	elif radix == 64:
		return base64(md5_obj.digest())

def base64(data):
	import base64
	return base64.b64encode(data)

def sha256(data):
	import hashlib
	sha_obj = hashlib.sha256()
	sha_obj.update(data)
	return sha_obj.hexdigest()

def sha1(data, radix=16):
	import hashlib
	sha_obj = hashlib.sha1()
	sha_obj.update(data)
	if radix == 16:
		return sha_obj.hexdigest()
	elif radix == 64:
		return base64(sha_obj.digest())

def generate_random_hex():
	hex_dig = '1234567890abcdef'
	return ''.join([random.choice(hex_dig) for _ in range(16)])

def _now():
	return datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M:%S")


def execute_request(url, httpmethod, headers, params, data, log_response=True, auth=None, files=None, **kwargs):
	"""Send one HTTP request.

	Returns a dict that always carries 'res' (the requests.Response or None),
	'status' (1 = we got an answer, 0 = the request blew up), 'code' (the HTTP
	status) and 'data' (the response body).  Callers need 'code' to tell a
	rejected request from an accepted one -- a 4xx body is still an answer.
	"""
	log_data = {'status': 0, 'error': None, 'code': None, 'data': ''}
	print(">>>[%s] %s %s\nParams:%s\nHeaders:%s\nData:%s"
	      % (_now(), httpmethod, url, str(params), str(headers), str(data)))
	if debug:
		print("url is %s, \n httpmethod is: %s, \n headers is: %s, \n params is: %s, \n data is: %s,"
		      % (url, httpmethod, headers, params, data))
		input('press enter')

	method = (httpmethod or 'get').lower()
	if method not in ('get', 'post', 'put', 'head'):
		raise ValueError("unsupported httpmethod %r" % httpmethod)

	timeout = 60 if method in ('put', 'head') else 30
	r = None
	try:
		fn = getattr(requests, method)
		with closing(fn(url, headers=headers, params=params, data=data,
		                timeout=timeout, verify=False, auth=auth,
		                files=files, **kwargs)) as resp:
			r = resp
		log_data['data'] = r.text
		log_data['code'] = r.status_code
		log_data['status'] = 1
	except Exception:
		traceback.print_exc(file=sys.stdout)
		tb = traceback.format_exc().split('\n')
		log_data['error'] = tb[len(tb) - 2] if len(tb) > 1 else 'request failed'

	if log_data['status'] == 1 and log_response:
		print("<<<[%s] %s Data:%s" % (_now(), str(log_data['code']),
		                               log_data['data'][:2000]))
	elif log_data['status'] == 0:
		print("<<<[%s] Error:%s" % (_now(), str(log_data['error'])))
	log_data['res'] = r

	try:
		if r:
			log_data['req_length'] = (
				len(str(r.request.method)) + len(str(r.request.url)) +
				len(str(r.request.headers)) +
				len(str(r.request.body) if r.request.body else []))
		else:
			log_data['req_length'] = 0
	except Exception:
		log_data['req_length'] = 0

	try:
		cl = 0
		if r is not None:
			if r.cookies:
				cl += len(str(r.cookies))
			if r.content:
				cl += len(str(r.content))
			if r.headers:
				cl += len(str(r.headers))
		log_data['res_length'] = int(cl)
	except Exception:
		log_data['res_length'] = 0

	return log_data

